    static IEnumerable<Control> Walk(Control c){yield return c;foreach(Control child in c.Controls)foreach(var v in Walk(child))yield return v;}
    static void Show(Form f){f.StartPosition=FormStartPosition.Manual;f.Location=new(-19000,-19000);f.Show();Application.DoEvents();}
    public static void Run(string report){using var host=new Form{Opacity=0,ShowInTaskbar=false};host.Shown+=async(_,_)=>{try{var checks=await Check(Path.GetDirectoryName(report)!);File.WriteAllText(report,JsonSerializer.Serialize(new{ok=checks.Values.All(v=>v),checks,external_actions=0},new JsonSerializerOptions{WriteIndented=true}));}catch(Exception e){File.WriteAllText(report,JsonSerializer.Serialize(new{ok=false,error=e.ToString()}));}finally{host.Close();}};Application.Run(host);}
    static async Task<Dictionary<string,bool>> Check(string dir)
    {
        Directory.CreateDirectory(dir);var c=new Dictionary<string,bool>();string fixture=Path.Combine(dir,"fixtures-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(fixture);string oldRoot=SkinLibrary.Root;SkinLibrary.Root=Path.Combine(fixture,"skins");
        try{
            string file=Path.Combine(fixture,"中文 文件.txt");File.WriteAllText(file,"fixture");c["file_absolute_path"]=LocalPath.Resolve(file)==file;c["folder_absolute_path"]=LocalPath.Resolve(fixture)==fixture;c["quoted_path"]=LocalPath.Resolve("\""+file+"\"")==file;Environment.SetEnvironmentVariable("LEO52_TEST",fixture);c["environment_path"]=LocalPath.Resolve("%LEO52_TEST%\\中文 文件.txt")==file;c["url_is_not_path"]=!LocalPath.LooksLike("https://example.com/a");c["missing_path_error"]=Throws(()=>LocalPath.Resolve(Path.Combine(fixture,"missing")));c["path_recognized_without_catalog"]=LauncherForm.IsCommand(file)&&QuickRouter.Route(file).Value=="path_open";
            var app=new LocalApplication(Guid.NewGuid().ToString("N"),"测试播放器",Environment.ProcessPath!);LocalApplications.Validate(app);c["app_valid"]=true;c["invalid_path_rejected"]=Throws(()=>LocalApplications.Validate(app with{Path=file}));c["empty_name_rejected"]=Throws(()=>LocalApplications.Validate(app with{Name=""}));var prefs=new Preferences{ApplicationModules=[app]};var restored=LocalApplications.Clone(prefs);c["app_roundtrip"]=restored.ApplicationModules.Single()==app;
            int calls=0;string last="";using var bus=new ActionDispatcher(prefs,(a,v,t)=>{calls++;last=a+":"+v;return Task.FromResult("ok");},new ExtensionStore(Path.Combine(fixture,"extensions")));
            c["app_independent_module"]=bus.Modules.Any(m=>m.Id=="local:"+app.Id&&m.Enabled);await bus.ExecuteAsync(new("local:"+app.Id,"","search"));c["app_uses_shared_action"]=last=="local_app_open:"+app.Id;await bus.ExecuteTextAsync(file,"search");c["path_shared_action"]=last=="path_open:"+file;prefs.ApplicationModules[0]=app with{Enabled=false};c["disabled_module_live"]=!bus.Modules.Single(m=>m.Id=="local:"+app.Id).Enabled;try{await bus.ExecuteAsync(new("local:"+app.Id));c["disabled_no_execution"]=false;}catch(InvalidOperationException){c["disabled_no_execution"]=calls==2;}prefs.ApplicationModules.Clear();c["removed_module_gone"]=!bus.Modules.Any(m=>m.Id=="local:"+app.Id);prefs.ApplicationModules.Add(app);
            string iconPath=Path.Combine(fixture,"icon.png");using(var image=new Bitmap(32,32)){using var g=Graphics.FromImage(image);g.Clear(Color.Lime);image.Save(iconPath);}prefs.ApplicationModules[0]=app with{Icon=iconPath};using(var glyph=new GlyphButton("terminal"){Size=new(28,24),Image=LocalApplications.Icon(iconPath)}){using var render=new Bitmap(28,24);glyph.DrawToBitmap(render,glyph.ClientRectangle);c["custom_icon_replaces_glyph"]=render.GetPixel(14,12).G>220&&render.GetPixel(14,12).R<20;glyph.Image!.Dispose();}c["bad_icon_fallback"]=LocalApplications.Icon(file)==null;
            using(var launcher=new LauncherForm(prefs,()=>{},true,true)){int media=0,launches=0;launcher.MediaRequested=()=>media++;launcher.ActionRequested=(a,v,t)=>{if(a=="local:"+app.Id)launches++;return Task.FromResult("ok");};Show(launcher);launcher.Open();var row=Walk(launcher).OfType<FlowLayoutPanel>().Single(p=>p.Controls.OfType<Button>().Any(b=>b.AccessibleName=="PotPlayer · 媒体控制"));var names=row.Controls.OfType<Button>().Select(b=>b.AccessibleName).ToArray();c["shortcut_order"]=names.SequenceEqual(new[]{"足球赛程","QQ音乐点歌","PotPlayer · 媒体控制",app.Name});row.Controls.OfType<Button>().Single(b=>b.AccessibleName=="PotPlayer · 媒体控制").PerformClick();row.Controls.OfType<Button>().Single(b=>b.AccessibleName==app.Name).PerformClick();c["media_button_callback"]=media==1;c["football_button_reparenting"]=launcher.VerifyFootballEntry();launcher.Open();c["music_button_reparenting"]=launcher.VerifyMusicEntry();launcher.Open();c["custom_button_dispatch"]=launches==1;prefs.MediaModule=false;launcher.RefreshModules();c["media_disable_hides_button"]=!Walk(launcher).OfType<Button>().Any(b=>b.AccessibleName=="PotPlayer · 媒体控制");prefs.MusicModule=false;launcher.RefreshModules();c["music_disable_hides_button"]=!Walk(launcher).OfType<Button>().Any(b=>b.AccessibleName=="QQ音乐点歌");for(int i=0;i<18;i++)prefs.ApplicationModules.Add(app with{Id=Guid.NewGuid().ToString("N"),Name="测试"+i});launcher.RefreshModules();c["many_shortcuts_overflow"]=row.Controls.Cast<Control>().Any(b=>!b.Visible)&&row.Parent!.Right<=377;c["overflow_entry_visible"]=Walk(launcher).OfType<Button>().Single(b=>b.AccessibleName=="更多快捷功能").Visible;c["buttons_clear_slider"]=row.Parent!.Right<launcher.Controls.OfType<MsnSlider>().Single().Left;launcher.Close();}
            using(var view=new ModulesView(new Preferences{ModuleExecutables=new(){["clash"]=Path.Combine(fixture,"missing.exe")}},true)){var draft=new Preferences();view.Apply(draft,false);c["invalid_existing_path_can_be_edited"]=draft.ModuleExecutables.ContainsKey("clash");}
            var output=new Preferences();using(var manager=new LocalApplicationsForm(output)){Show(manager);Walk(manager).OfType<Button>().Single(b=>b.Text=="启用 / 停用").PerformClick();c["manager_draft_not_applied"]=output.TerminalModule;Walk(manager).OfType<Button>().Single(b=>b.Text=="确定").PerformClick();c["manager_confirm_applies"]=!output.TerminalModule;}
            using(var editor=new ApplicationEditor(null,null,null)){Show(editor);var fields=Walk(editor).OfType<TextBox>().ToArray();fields[0].Text="本地应用";fields[1].Text=Environment.ProcessPath!;fields[2].Text=iconPath;Walk(editor).OfType<Button>().Single(b=>b.Text=="确定").PerformClick();c["new_app_editor"]=editor.Result is {Name:"本地应用",Enabled:true}&&editor.Result.Icon==iconPath;}
            var first=SkinLibrary.Duplicate("83","独立巴萨");c["new_skin_unique"]=first.Id.StartsWith("custom:")&&first.Id!="83"&&SkinLibrary.Load().Length==1;c["default_clone_preserves_original_art"]=AnimationSkin.Name(first.Id)==null;var second=SkinLibrary.Duplicate(first.Id,"独立第二套");c["duplicate_is_independent"]=second.Id!=first.Id&&File.Exists(SkinLibrary.TexturePath(first.Id))&&File.Exists(SkinLibrary.TexturePath(second.Id));SkinLibrary.Remove(first.Id);c["remove_preserves_other_skin"]=SkinLibrary.Find(second.Id)!=null;
            string jersey=Path.Combine(fixture,"jersey.png");SkinLibrary.ExportTemplate(jersey);var imported=SkinLibrary.Import(jersey,"新队服","382");c["custom_png_independent"]=imported.BaseTheme=="382"&&AnimationSkin.Name(imported.Id)==imported.Id&&File.Exists(jersey);using(var form=new NewSkinForm("382","测试新皮肤")){Show(form);Walk(form).OfType<Button>().Single(b=>b.Text=="创建皮肤").PerformClick();c["create_skin_dialog"]=form.Result is {Name:"测试新皮肤",BaseTheme:"independent"};}c["builtin_skins_preserved"]=SkinSelection.Options.Length==5;
            c["module_icon_roundtrip"]=LocalApplications.Clone(new Preferences{ModuleIcons=new(){["clash"]=iconPath}}).ModuleIcons["clash"]==iconPath;
            return c;
        }finally{SkinLibrary.Root=oldRoot;Environment.SetEnvironmentVariable("LEO52_TEST",null);}
    }
    static bool Throws(Action action){try{action();return false;}catch(ArgumentException){return true;}catch(IOException){return true;}}
